WITH cleaned AS (SELECT *, CASE WHEN status = 'SUCCESS' THEN 1 ELSE 0 END AS is_success FROM payments WHERE paid_at >= TO_TIMESTAMP('2023-06-22 09:00:00') AND order_id IS NULL), with_windows AS (SELECT id, order_id, method, paid_at, MIN(amount) OVER (PARTITION BY status ORDER BY is_success, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_amount, SUM(amount) OVER (PARTITION BY status ORDER BY is_success, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_amount, MAX(amount) OVER (PARTITION BY status ORDER BY is_success, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_amount, COUNT(amount) OVER (PARTITION BY status ORDER BY is_success, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_amount FROM cleaned WHERE order_id IN (1, 8, 35)), scored AS (SELECT id, order_id, method, running_max_amount, AVG(running_sum_amount) OVER w_recent AS running_sum_amount_avg_6, AVG(running_min_amount) OVER w_hist AS running_min_amount_avg_2, COUNT(running_max_amount) OVER (PARTITION BY order_id ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS running_max_amount_count_90d, LEAD(running_count_amount, 2) OVER (PARTITION BY order_id ORDER BY running_min_amount, id) AS next_running_count_amount FROM with_windows WINDOW w_recent AS (PARTITION BY method ORDER BY running_sum_amount, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW), w_hist AS (PARTITION BY DATE_TRUNC('MONTH', paid_at), method ORDER BY running_max_amount, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY method ORDER BY next_running_count_amount NULLS LAST, id) AS row_num FROM scored) ranked WHERE row_num = 1), enriched AS (SELECT *, LEAD(next_running_count_amount, 2, 0) OVER w_running AS next_next_running_count_amount, FIRST_VALUE(next_running_count_amount, TRUE) OVER w_ordered AS first_known_next_running_count_amount, SUM(running_min_amount_avg_2) OVER (ORDER BY running_sum_amount_avg_6, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_running_min_amount_avg_2 FROM ranked WINDOW w_running AS (PARTITION BY order_id ORDER BY running_min_amount_avg_2, id), w_ordered AS (PARTITION BY order_id, method ORDER BY running_max_amount_count_90d, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT method, CASE WHEN running_min_amount_avg_2 >= 1690 THEN 'HIGH' ELSE 'LOW' END AS running_min_amount_avg_2_tier, COUNT_IF(method = 'cash') AS cash_events, SORT_ARRAY(COLLECT_SET(method)) AS method_list, SORT_ARRAY(COLLECT_SET(method)) AS method_list_2, MIN(next_next_running_count_amount) AS min_next_next_running_count_amount, COUNT(*) FILTER (WHERE method = 'promptpay') AS promptpay_rows FROM enriched GROUP BY method, CASE WHEN running_min_amount_avg_2 >= 1690 THEN 'HIGH' ELSE 'LOW' END ORDER BY running_min_amount_avg_2_tier DESC NULLS FIRST
